    },
    {
      "hint": 4,
      "original": "Small cars—defined as vehicles under four metres in length with engines up to 1,000cc (petrol) or 1,200cc (diesel)—will now attract 12% GST with an additional cess of 3%",
      "corrected": "Small cars—defined as vehicles under four metres in length with engines up to 1,200cc (petrol) or 1,500cc (diesel)—will now attract 18% GST without any additional cess"
    },
    {
      "hint": 5,
      "original": "will now be taxed at 28% GST",
      "corrected": "will now be taxed at 40% GST"
    }
  ]
